public record CuentaDto(
    Long id,
    String nombre,
    String email,
    double saldo,
    boolean activa
) { }

public record CrearCuentaRequest(
    @NotBlank String nombre,
    @Email String email
) { }

public record ErrorResponse(
    int status,
    String message,
    LocalDateTime timestamp
) { }

@JsonInclude(JsonInclude.Include.NON_NULL)
public record UsuarioDto(
    Long id,
    String nombre,
    @JsonProperty("email_address") String email
) { }

ObjectMapper mapper = new ObjectMapper()
    .registerModule(new JavaTimeModule())
    .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);

try {
    CuentaDto cuenta = mapper.readValue(json, CuentaDto.class);
} catch (JsonMappingException e) {
    throw new BadRequestException("JSON invalido: " + e.getMessage());
} catch (JsonProcessingException e) {
    throw new BadRequestException("Error de procesamiento JSON");
}

public record CrearCuentaRequest(
    @NotBlank(message = "El nombre es obligatorio")
    String nombre,
    @Email(message = "Email invalido")
    String email,
    @Min(value = 0, message = "El saldo no puede ser negativo")
    double saldo
) { }

